function verifyCharacterCodes(assertEqual) {
  assertEqual(String.fromCharCode(65), "A");
  assertEqual(String.fromCharCode(66), "B");
  assertEqual(String.fromCharCode(67), "C");
  assertEqual(String.fromCharCode(68), "D");
  assertEqual(String.fromCharCode(69), "E");
  assertEqual(String.fromCharCode(70), "F");
}
